manifest=[]
for n,(bid,title,author,death,year,genre,repo,blurb,tags,signals,ca,cb,mark) in enumerate(rows):
    is_approved=(bid=='pride-and-prejudice')
    record={'id':bid,'title':title,'author':author,'authorDeathYear':death,'firstPublicationYear':year,'originalLanguage':'en',
      'translation':False,'genre':genre,'standardEbooksRepo':repo,'sourceUrl':'https://standardebooks.org/ebooks?query='+title.replace(' ','%20'),
      'blurb':blurb,'tags':tags.split(','),'storySignals':signals.split('|'),'colors':[ca,cb],'mark':mark,'featured':max(0,30-n),
      'rights':{'decision':'approved' if is_approved else 'pending',
                'reviewer':'initial-edition-review' if is_approved else '',
                'reviewedAt':'2026-11-04' if is_approved else '',
                'jurisdictions':['AU','US'] if is_approved else [],
                'edition':'Jane Austen original 1813 English text; Standard Ebooks CC0 editorial contribution' if is_approved else '',
                'notes':'Original English work first published 1813; author died 1817; source-edition contribution is CC0. Full first chapter only in initial release.' if is_approved else 'Awaiting individual edition, translation, and jurisdiction review.'}}
    manifest.append(record)
p=(ROOT/'content'/'rights_manifest.json');p.write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');print(len(manifest),'rights manifest candidates')
